'use strict';
const routeData={tech:{title:'把实现能力，补成产品判断。',body:'选一个亲自完成的技术项目，补上用户原来的做法、你比较过的方案和不做的理由。让代码出现在解释约束的地方。',output:'今天交付：一页取舍说明 + 一条可核实的项目表述。'},business:{title:'把分析结论，落到可执行方案。',body:'从一个具体用户任务开始，补齐关键流程、字段与错误状态。用小数据样例计算指标，再说明如何验证。',output:'今天交付：一条完整任务原型 + 指标分子与分母。'},experienced:{title:'把参与经历，讲清自己的贡献。',body:'从真实项目选一个重要决定，写清你拥有的权限、原始依据、协作者和最终结果。保留保密边界与归因限制。',output:'今天交付：一页贡献证据 + 一个可承受追问的案例。'}};
document.querySelectorAll('[data-route]').forEach(button=>button.addEventListener('click',()=>{const data=routeData[button.dataset.route];document.querySelectorAll('[data-route]').forEach(x=>x.setAttribute('aria-selected',String(x===button)));const box=document.getElementById('route-answer');box.querySelector('h3').textContent=data.title;box.querySelector('.route-body').textContent=data.body;box.querySelector('.route-output').textContent=data.output;}));
const search=document.getElementById('chapter-search');if(search)search.addEventListener('input',()=>{const term=search.value.trim().toLowerCase();let visible=0;document.querySelectorAll('.chapter-card').forEach(card=>{const match=!term||card.dataset.search.toLowerCase().includes(term);card.hidden=!match;if(match)visible++;});document.getElementById('search-count').textContent=visible?'找到 '+visible+' 个章节':'没有匹配章节。试试“毕业”“研究”“AI”或“面试”。';});
document.querySelectorAll('[data-copy-wechat]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText('AIPMAndy');button.textContent='已复制';}catch(e){button.textContent='微信：AIPMAndy';}}));
